  const plain = s => String(s || '').replace(/<[^>]+>/g, '');
  const freeze = o => { for (const v of Object.values(o)) if (v && typeof v === 'object') freeze(v); return Object.freeze(o); };
  for (const e of LIST) {
    for (const k of ['common', 'avoid', 'cadet', 'rulings', 'distinct', 'basis', 'fixed']) if (!e[k]) e[k] = [];
    if (!('icao' in e)) e.icao = null; if (!('abbr' in e)) e.abbr = null; if (!('jcabForm' in e)) e.jcabForm = null;
    if (!('law' in e)) e.law = null; if (!('note' in e)) e.note = ''; if (!('owner' in e)) e.owner = false;
  }
  const BY_ID = new Map(LIST.map(e => [e.id, e]));
  // every Japanese or English name the entry answers to. The abbreviation keeps its tags: V<sub>MC</sub> (最小操縦速度)
  // and VMC (有視界気象状態) are two names (DESIGN 3.5)
  const namesOf = e => [...new Set([e.formal, ...e.common, ...(e.abbr ? [e.abbr] : []), ...(e.jcabForm ? [e.jcabForm] : []), ...(e.law ? [e.law] : [])])];
  const BY_NAME = new Map();
  for (const e of LIST) for (const n of [...namesOf(e), ...e.avoid]) if (!BY_NAME.has(n)) BY_NAME.set(n, e);
  const BY_EN = new Map(LIST.map(e => [e.en.toLowerCase(), e]));
  const byId = id => BY_ID.get(id) || null;
  // a name → its entry: exact (formal, common, abbreviation, JCAB's spelling, the law's name, the avoided words), then the
  // same without tags (<b>…</b>), then the English without regard to case; null when the table does not know it
  const find = name => {
    const raw = String(name || '').trim(), n = plain(raw).trim();
    return BY_NAME.get(raw) || BY_NAME.get(n) || BY_EN.get(n.toLowerCase()) || null;
  };
  const names = id => { const e = byId(id); return e ? namesOf(e) : []; };
  // the form of a chapter's first use (DESIGN 3.5): 正式名（通称、English）
  const firstUse = id => { const e = byId(id); if (!e) return ''; const inner = [e.common[0], e.en].filter(Boolean); return `${e.formal}（${inner.join('、')}）`; };
  const ofRuling = rid => LIST.filter(e => e.rulings.includes(rid));
  const cadetNames = () => [...new Set(LIST.flatMap(e => e.cadet))];

